INSERT INTO `courses` (`id`, `title`, `abbreviation`, `category_id`, `cover_image`, `description`, `overview`, `duration_months`, `weeks_of_study`, `days_of_study`, `hours_of_study`, `study_schedule`, `course_fee`, `last_sequence`, `is_active`, `approval_status`, `created_by`, `created_at`, `updated_at`, `rejection_reason`, `reviewed_by`, `reviewed_at`) VALUES
(1, 'Generative AI', 'AI', 3, '/uploads/courses/covers/1783934350_76508629741a.jpg', 'Introduction to Generative AI & Prompt Design\r\nText Generation & Marketing Copy (ChatGPT, Gemini)\r\nAI Image Generation (Midjourney, DALL-E, Stable Diffusion)\r\nCoding Assistance with Github Copilot & cursor\r\nCreating High-Converting Ad Copy & Assets\r\nProductivity Workflows & Automations', 'Create premium copy, imagery, and software code using modern generative tools.', 3, NULL, NULL, NULL, NULL, 60000.00, 1, 1, 'approved', 8, '2026-07-01 03:12:33', '2026-07-13 09:19:10', NULL, NULL, NULL),
(2, 'Web Development', 'WEB', 8, '/uploads/courses/covers/1783931608_8316887582da.png', 'Web Design Principles & UI Layouts\r\nHTML5 Semantic Tags & CSS Layouts (Flexbox/Grid)\r\nResponsive Web Design with Tailwind CSS\r\nInteractivity with JavaScript\r\nDjango \r\nPHP\r\nSEO Best Practices & Web Performance Tuning\r\nHosting, Domains, and Deploying Static Sites', 'Create fast, responsive, and SEO-friendly websites using standard modern frameworks.', 6, NULL, NULL, NULL, NULL, 120000.00, 0, 1, 'approved', 8, '2026-07-01 03:45:59', '2026-07-18 10:08:37', NULL, NULL, NULL),
(7, 'software development', 'SE', 9, '/uploads/courses/covers/1783941927_9d8cd1c45e20.png', 'Python Programming\r\nHTML5, CSS3, Modern JavaScript (ES6+)\r\nReact.js and Tailwind CSS Frontends\r\nDjango, DRF and RESTful APIs\r\nRelational and NoSQL Databases (PostgreSQL,SQLITE3)\r\nmobile development\r\nGit, GitHub, and Cloud Deployment (Vercel, Render,Aws)\r\nMachine learning\r\nCapstone Projects & Technical Interview Prep', 'Frontend, Backend , mobile development and Full Stack Development using modern technologies.', 18, NULL, NULL, NULL, NULL, 300000.00, 0, 1, 'approved', NULL, '2026-07-01 15:18:06', '2026-07-18 09:43:54', NULL, NULL, NULL),
(8, 'Python Programming', 'PY', 9, '/uploads/courses/covers/1783930797_f16fe576b9f7.jpg', 'Python Basics, Variables & Data Types\r\nControl Flows, Loops & Functions\r\nObject-Oriented Programming (OOP) in Python\r\nWorking with Databases & File I/O]\r\nWeb Scraping & API Integrations with Requests\r\nBuilding Automation Scripts & CLI Tools', 'Master general-purpose Python programming, object-oriented concepts, and automation scripting.', 3, NULL, NULL, NULL, NULL, 60000.00, 0, 1, 'approved', 8, '2026-07-11 11:30:32', '2026-07-19 18:11:40', NULL, NULL, NULL),
(9, 'Ai automation', 'AA', 3, '/uploads/courses/covers/1783934362_173b982b2470.webp', 'Workflow Automation Concepts (triggers, actions)\r\nUsing Make.com & Zapier to connect apps\r\nWriting Python/JS connectors for API integrations\r\nAutomating Email/Slack tasks with AI agents\r\nExtracting and parsing unstructured documents\r\n', 'Automate repetitive workflows and connect platforms using AI pipelines', 1, NULL, NULL, NULL, NULL, 30000.00, 0, 1, 'approved', 8, '2026-07-13 09:18:55', '2026-07-13 09:19:22', NULL, NULL, NULL),
(10, 'web hosting', 'WH', 4, '/uploads/courses/covers/1783936898_2821de77a682.jpg', 'Learn how websites go live on the internet with our Web Hosting course. Master domain setup, cPanel, SSL certificates, email hosting, WordPress installation, website deployment, backups, security, and server management. Gain practical skills to host business websites, client projects, and web applications with confidence. This course is perfect for beginners, aspiring web developers, freelancers, and entrepreneurs who want to build, launch, and manage professional websites while creating valuable career and business opportunities.\r\n', 'Web hosting is a service that securely stores your website\'s files on a physical or virtual server, making them accessible to anyone connected to the internet', 1, NULL, NULL, NULL, NULL, 3500.00, 0, 1, 'approved', 8, '2026-07-13 10:01:38', '2026-07-20 10:48:17', NULL, NULL, NULL),
(11, 'Mpesa integration', 'MPESA', 4, '/uploads/courses/covers/1783937183_d560df89ead4.png', 'M-Pesa Integration teaches you how to connect M-Pesa payments to websites, mobile apps, and business systems. You will learn how to receive payments, confirm transactions automatically, process customer payments, generate payment requests, and manage records using the M-Pesa Daraja API. The course includes hands on projects that help you build secure payment solutions used by businesses across Kenya. It is a valuable skill for software developers, freelancers, and entrepreneurs who want to create modern applications with seamless mobile payment features.\r\n', 'learn how to do mpesa integration B2C, C2B among others with STK push.', 0, NULL, 3, 2, NULL, 2500.00, 0, 1, 'approved', 8, '2026-07-13 10:06:23', '2026-07-23 08:55:06', NULL, NULL, NULL),
(12, 'Data analytics', 'DT', 5, '/uploads/courses/covers/1783938040_4941a13121be.jpg', 'Data Manipulation using MS Excel & Google Sheets\r\nSQL Databases (Structuring & Querying Data)\r\nData Visualization with Tableau & Power BI\r\nIntroduction to Python for Data Science (Pandas, NumPy)\r\nStatistical Analysis & Decision Making\r\nBuilding Interactive Business Dashboards', 'Analyze complex data, build beautiful dashboards, and drive business intelligence.', 1, NULL, NULL, NULL, NULL, 120000.00, 0, 1, 'approved', 8, '2026-07-13 10:20:40', '2026-07-13 10:20:40', NULL, NULL, NULL),
(13, 'cubersecurity', 'CS', 7, '/uploads/courses/covers/1783938740_fe23d09f6971.jpg', 'Cybersecurity teaches you how to protect computers, websites, networks, and data from hackers and online threats. You will learn about ethical hacking, password security, malware, network protection, encryption, and how to identify and fix security risks. Through practical labs and real world projects, you will gain hands on experience using tools and techniques trusted by security professionals. This course is ideal for students who want to build a career in IT security, protect businesses, and stay ahead in one of the fastest growing technology fields.\r\n', 'Cybersecurity is the practice of protecting networks, devices, and data from unauthorized digital access, attacks, and breaches', 6, 12, NULL, 2, 'Mon, Tue, Wed, Fri', 120000.00, 1, 1, 'approved', 8, '2026-07-13 10:32:20', '2026-07-23 02:33:10', NULL, NULL, NULL),
(14, 'machine learning', 'ML', 5, '/uploads/courses/covers/1783938888_d484a5d50a21.png', 'Python for Machine Learning (Scikit-Learn, SciPy)\r\nSupervised Learning (Regression, Classification)\r\nUnsupervised Learning (Clustering, Dimensionality)\r\nNeural Networks & Deep Learning Basics\r\nModel Evaluation, Hyperparameter Tuning\r\nDeploying ML Models as Microservices', 'Build and deploy intelligent predictive models from scratch using modern frameworks.', 6, NULL, NULL, NULL, NULL, 120000.00, 0, 1, 'approved', 8, '2026-07-13 10:34:48', '2026-07-13 10:35:34', NULL, NULL, NULL),
(15, 'AI and digital marketing', 'AD', 3, '/uploads/courses/covers/1783939484_4e1d178145b3.jpg', 'AI in Modern Digital Marketing Channels\r\nAI Copywriting & Ad Creative Generation\r\nSEO and Keyword Research with AI Assistance\r\nSocial Media Algorithm Strategies & Calendar Planning\r\nMeta & Google Paid Ad Campaigns Optimization\r\nMarketing Analytics & AI-Driven Insights', 'Master content creation, ad targeting, and digital marketing powered by AI.', 3, NULL, NULL, NULL, NULL, 60000.00, 0, 1, 'approved', 8, '2026-07-13 10:41:52', '2026-07-21 03:51:46', NULL, NULL, NULL),
(16, 'Social media management', 'SM', 4, '/uploads/courses/covers/1783941820_3a9643633715.webp', 'Social Media Strategy & Platform Demographics\r\nContent Creation & Editorial Calendars\r\nCommunity Management & Engagement Tactics\r\nAnalytics, KPIs, and Growth Reporting\r\nPaid Social Campaigns & Audience Targeting\r\nInfluencer Marketing & Brand Partnerships', 'Learn content strategy, community engagement, brand voice, and digital ad campaigns.', 1, NULL, NULL, NULL, NULL, 20000.00, 0, 1, 'approved', 8, '2026-07-13 10:43:22', '2026-07-13 11:23:40', NULL, NULL, NULL),
(17, 'Virtual Assistance', 'VA', 4, '/uploads/courses/covers/1783939746_c77b3b841f99.webp', 'A virtual assistant (VA) is a self-employed remote professional who provides administrative, technical, or creative support to businesses and entrepreneurs from a home office. Tasks typically include managing emails and calendars, data entry, social media management, and online research', 'learn how to do remote and professional administrative, technical, or creative support services to clients. ', 1, NULL, NULL, NULL, NULL, 20000.00, 0, 1, 'approved', 8, '2026-07-13 10:49:06', '2026-07-13 10:49:06', NULL, NULL, NULL),
(18, 'software development', 'SD', 9, '/uploads/courses/covers/1783941376_5f04f882105f.jpg', 'Python programing\r\nHTML5, CSS3, Modern JavaScript (ES6+)\r\nReact.js and Tailwind CSS Frontends\r\nDjango, php, and RESTful APIs\r\nRelational and NoSQL Databases (PostgreSQL, SQL lite)\r\nGit, GitHub, and Cloud Deployment (Vercel, Render)\r\nPayment integrations\r\nCapstone Projects & Technical Interview Prep\r\nMachine learning basics', 'lean a comprehensive Frontend, Backend, machine learning basics and Full Stack Development using modern technologies.', 15, 60, NULL, 1256, NULL, 240000.00, 0, 1, 'approved', 8, '2026-07-13 11:16:16', '2026-07-21 05:36:34', NULL, NULL, NULL),
(19, 'Diploma in IT & AI', 'IT', 9, '/uploads/courses/covers/1784368366_9d2efb611016.png', 'Networking\r\nCybersecurity\r\nHardware and Technical Support\r\nAI and Generative AI\r\nRobotics and IoT\r\nWeb and Software Development\r\nBig Data and Data Analytics\r\nProject Management', 'This equips you with practical skills in networking, cybersecurity, AI, robotics, hardware support, and software development. It prepares you for high demand technology careers through hands on training and real world projects.', 18, NULL, NULL, NULL, NULL, 300000.00, 0, 1, 'approved', 8, '2026-07-18 09:52:46', '2026-07-19 16:53:15', NULL, NULL, NULL),
(20, 'pentagon', 'PYYY', 5, NULL, 'bctrfughuiftyufdxytfgiuhjkughytdfcytrg', 'ppppppppppp', 1, NULL, NULL, NULL, NULL, 6000.00, 0, 0, 'approved', 8, '2026-07-19 18:10:26', '2026-07-19 18:11:48', NULL, NULL, NULL),
(21, 'Diploma in Cybersecurity and AI', 'CSA', 7, '/uploads/courses/covers/1784541896_b2d9e06d15a4.jpg', 'Computer Systems and Networking\r\nPython Programming and Automation\r\nLinux Administration\r\nCybersecurity Fundamentals\r\nEthical Hacking and Penetration Testing\r\nCloud Computing and Cloud Security\r\nArtificial Intelligence and Machine Learning\r\nGenerative AI and AI Automation\r\nDigital Forensics and Incident Response\r\nCapstone Project, Industrial Attachment and Professional Development', 'AI cybersecurity uses machine learning algorithms to automate threat detection, analyze vast amounts of data, and respond to security incidents in real time.', 18, NULL, NULL, NULL, NULL, 300000.00, 0, 1, 'approved', 8, '2026-07-20 09:53:38', '2026-07-20 10:04:56', NULL, NULL, NULL),
(22, 'Diploma in Data Science', 'DS', 5, '/uploads/courses/covers/1784542163_8b8b08c65177.jpg', 'Python Programming\r\nMathematics and Statistics for Data Science\r\n Data Collection and Data Management\r\nSQL and Database Systems\r\nData Analysis and Visualization\r\nMachine Learning\r\nDeep Learning and Artificial Intelligence\r\nBig Data Technologies\r\nData Engineering and Cloud Computing\r\nCapstone Project, Industry Attachment and Professional Development\r\n', 'Data Science combines statistics, programming, and business knowledge to collect, analyze, and interpret data. It helps organizations build predictive models, solve problems, and make data driven decisions.\r\n', 18, NULL, NULL, NULL, NULL, 300000.00, 0, 1, 'approved', 8, '2026-07-20 10:09:23', '2026-07-20 10:09:23', NULL, NULL, NULL),
(23, 'UI and UX Design', 'UI', 8, '/uploads/courses/covers/1784542781_a6006529b829.png', 'Figma \r\nWireframing\r\nPrototyping \r\nUser experience', 'UI/UX Design teaches you how to create websites and mobile apps that are both attractive and easy to use. Learn to design modern digital experiences that improve user satisfaction and prepare you for careers in tech and product design.\r\n', 2, NULL, NULL, NULL, NULL, 40000.00, 0, 1, 'approved', 8, '2026-07-20 10:19:41', '2026-07-20 10:19:41', NULL, NULL, NULL),
(24, 'Data Analysis with Excel & Power BI', 'DAS', 5, '/uploads/courses/covers/1784543087_4e40e0986732.jpg', 'Microsoft Excel\r\nPower BI\r\nDashboards\r\nBusiness reporting', 'Learn how to turn data into insights using Excel and Power BI. Build interactive dashboards and reports that help businesses make smarter decisions.', 2, NULL, NULL, NULL, NULL, 40000.00, 0, 1, 'approved', 8, '2026-07-20 10:24:47', '2026-07-20 10:24:47', NULL, NULL, NULL),
(25, 'Wordpress web development', 'WP', 8, '/uploads/courses/covers/1784543886_5f69c28edf60.jpg', 'Website creation \r\nElementor\r\nWooCommerce\r\nWebsite maintenance', 'Learn to build professional websites without coding using WordPress, Elementor, and WooCommerce. Create business websites, online stores, and start earning as a freelance web developer.\r\n', 1, NULL, NULL, NULL, NULL, 30000.00, 0, 1, 'approved', 8, '2026-07-20 10:38:06', '2026-07-20 10:38:06', NULL, NULL, NULL),
(26, 'Video editing & content creation', 'VC', 4, '/uploads/courses/covers/1784544232_e12d91b80783.jpg', 'CapCut\r\nPremiere Pro\r\nTikTok\r\nYouTube content\r\nMeta', 'Master video editing and content creation for TikTok, YouTube, and social media. Learn to produce engaging videos that grow your audience and open opportunities in content creation and digital marketing.\r\n', 1, NULL, NULL, NULL, NULL, 30000.00, 0, 1, 'approved', 8, '2026-07-20 10:43:52', '2026-07-20 10:43:52', NULL, NULL, NULL),
(27, 'Digital marketing', 'DM', 4, '/uploads/courses/covers/1784544440_8c3507cb70ca.png', 'SEO\r\nGoogle Ads\r\nMeta Ads\r\nEmail marketing', 'Learn how to market businesses online using social media, SEO, and paid advertising. Gain practical skills to attract customers, grow brands, and build a career in digital marketing.\r\n', 1, NULL, NULL, NULL, NULL, 30000.00, 0, 1, 'approved', 8, '2026-07-20 10:47:20', '2026-07-20 10:47:20', NULL, NULL, NULL),
